INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Ethereum',
  'Ethereum compounded an early lead in developers, standards, liquidity and credible settlement. Moving to proof of stake reduced energy use and kept ETH central to security. EIP-1559 tied some blockspace demand to ETH burn. The rollup strategy expanded total ecosystem capacity, but it also moved much routine execution and fee capture away from L1. Ethereum thrives because it remains the deepest settlement network, not because every ecosystem transaction occurs on mainnet.',
  'mixed',
  'Ethereum is thriving. It remains the largest reviewed DeFi and dollar-stablecoin settlement base, generates substantial fees, has a $225.34 billion native asset and continues to ship protocol upgrades. The 62.14% TVL drawdown and migration of execution to rollups matter, but they describe a mature network under changing economics rather than a chain without demand.',
  '2026-08-03',
  '[{"id":"source:ethereum:intro","title":"Technical introduction to Ethereum","url":"https://ethereum.org/developers/docs/intro-to-ethereum/","publisher":"ethereum.org","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current proof-of-stake, EVM, gas, fee-burn and ETH security roles."},{"id":"source:ethereum:roadmap","title":"Ethereum roadmap","url":"https://ethereum.org/roadmap/","publisher":"ethereum.org","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated Merge, Shapella, Dencun, Pectra and Fusaka milestones plus explicitly future work."},{"id":"source:ethereum:withdrawals","title":"Ethereum staking withdrawals","url":"https://ethereum.org/staking/withdrawals/","publisher":"ethereum.org","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current validator withdrawals, compounding credentials and validator-count context."},{"id":"source:ethereum:rollups","title":"Ethereum scaling and rollups","url":"https://ethereum.org/developers/docs/scaling/","publisher":"ethereum.org","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current rollup-centric scaling model and the boundary between L1 and L2 execution."},{"id":"source:ethereum:eip1559","title":"EIP-1559 fee market change","url":"https://eips.ethereum.org/EIPS/eip-1559","publisher":"Ethereum Improvement Proposals","published_at":"2019-04-13","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Canonical base-fee burn and priority-fee design."},{"id":"source:ethereum:tvl","title":"Ethereum historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Ethereum","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:ethereum:volume","title":"Ethereum DEX volume API","url":"https://api.llama.fi/overview/dexs/Ethereum?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:ethereum:fees","title":"Ethereum fees API","url":"https://api.llama.fi/overview/fees/Ethereum?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:ethereum:revenue","title":"Ethereum revenue API","url":"https://api.llama.fi/overview/fees/Ethereum?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:ethereum:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Ethereum row and peggedUSD field."},{"id":"source:ethereum:market","title":"Ethereum token market data","url":"https://api.coingecko.com/api/v3/coins/ethereum","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:ethereum","type":"blockchain","slug":"ethereum","name":"Ethereum","aliases":[]},"classification":{"subtype":"general-purpose proof-of-stake L1","tags":["evm","proof_of_stake","rollup_settlement","eth"],"chains":["Ethereum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:ethereum:status"]},"outcome":{"label":"thriving","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:ethereum:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Ethereum is a general-purpose Layer 1 where validators settle EVM programs and secure ETH-denominated assets. It is also the settlement and data layer for many rollups. Those rollups are separate execution systems with their own operators and risks, so their users, TVL and fees should not be silently counted as Ethereum L1 activity.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:what_it_is:1","claim:ethereum:section:what_it_is:2"]},"what_happened":{"body":"Ethereum TVL was $40.68 billion at review, down 62.14% from the November 2021 series peak of $107.45 billion. It still held $146.91 billion of dollar stablecoins and processed $28.55 billion of thirty-day DEX volume. Thirty-day fees were $269.56 million and provider-attributed revenue was $49.69 million. ETH was $1,867.28, 62.25% below its recorded high.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:what_happened:1","claim:ethereum:section:what_happened:2"]},"why_this_outcome":{"body":"Ethereum compounded an early lead in developers, standards, liquidity and credible settlement. Moving to proof of stake reduced energy use and kept ETH central to security. EIP-1559 tied some blockspace demand to ETH burn. The rollup strategy expanded total ecosystem capacity, but it also moved much routine execution and fee capture away from L1. Ethereum thrives because it remains the deepest settlement network, not because every ecosystem transaction occurs on mainnet.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:why_this_outcome:1","claim:ethereum:section:why_this_outcome:2"]},"strategic_choices":{"body":"Ethereum replaced proof of work with proof of stake, adopted EIP-1559 base-fee burning, and chose a rollup-centric roadmap rather than maximizing all execution on L1. Dencun added blobs; Pectra expanded validator and wallet capabilities; Fusaka added PeerDAS. These choices favor neutral settlement, data availability and sustainable node operation over the cheapest possible L1 execution.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:strategic_choices:1","claim:ethereum:section:strategic_choices:2"]},"operating_model":{"body":"Validators stake ETH and run consensus and execution software to order and verify Ethereum blocks. EIP-1559 burns the base fee while priority fees and protocol rewards compensate validators. Withdrawals and compounding are available, with newer credentials supporting balances up to 2,048 ETH. Rollup sequencers and proof systems are outside Ethereum consensus even when their commitments and data land on Ethereum.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:operating_model:1","claim:ethereum:section:operating_model:2"]},"token_and_value_capture":{"body":"ETH pays L1 gas, backs validator security and is burned through the base fee. Supply can expand through validator rewards and contract when burns exceed issuance. ETH also serves as collateral across the ecosystem, but rollup activity only creates direct L1 value when it consumes Ethereum settlement or data. CoinGecko observed a $225.34 billion market capitalization and fully diluted value.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:token_and_value_capture:1","claim:ethereum:section:token_and_value_capture:2"]},"counterfactual":{"body":"Ethereum could have kept proof of work, preserving miner economics while retaining higher energy cost. It could have pursued much larger L1 blocks, lowering immediate execution cost while raising node requirements. It could also force more value capture from rollups, but doing so may reduce adoption or credible neutrality. The chosen path trades direct execution dominance for settlement breadth.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:counterfactual:1","claim:ethereum:section:counterfactual:2"]},"risks_and_unknowns":{"body":"Ethereum still faces stake and block-building concentration, correlated client bugs, smart-contract failures, governance coordination risk and competition from faster chains. Rollup fragmentation adds bridge, sequencer and proof-system risk that does not disappear because Ethereum settles the result. We do not yet know how much rollup growth will translate into durable blob fees, ETH burn or independent user demand.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:risks_and_unknowns:1","claim:ethereum:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Ethereum is thriving. It remains the largest reviewed DeFi and dollar-stablecoin settlement base, generates substantial fees, has a $225.34 billion native asset and continues to ship protocol upgrades. The 62.14% TVL drawdown and migration of execution to rollups matter, but they describe a mature network under changing economics rather than a chain without demand.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:lifecycle:1","claim:ethereum:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued dominance in high-value settlement and stablecoins while rollups handle more user execution. The call improves if blob demand, L1 fees, independent validators and retained developers grow together. It weakens if rollups use alternative data, stake or builders concentrate further, or competing chains win settlement liquidity. Watch blob fees, burn versus issuance, stablecoins, TVL, client share, builder concentration and rollup data posted to Ethereum.","as_of":"2026-08-03","claim_ids":["claim:ethereum:section:outlook_and_watch:1","claim:ethereum:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:ethereum:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":40683700138,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:ethereum:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:ethereum:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":146913084605.02255,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:ethereum:metric:stablecoins-latest"],"quality_flags":["not_equivalent_to_tvl"]},{"id":"metric:ethereum:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":28546821882.079998,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:ethereum:metric:dex-volume-30d"],"quality_flags":["l1_only"]},{"id":"metric:ethereum:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":269557428.17999977,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:ethereum:metric:fees-30d"],"quality_flags":["provider_scope"]},{"id":"me