"events[event:ethereum:fusaka]","assertion":"Fusaka added PeerDAS to improve rollup data availability.","value":"2025-12-03","as_of":"2025-12-03","confidence":"high","kind":"fact","source_ids":["source:ethereum:roadmap"],"evidence_locator":"Dated Fusaka milestone.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}}],"freshness":{"state":"current","last_reviewed_at":"2026-08-03T20:23:55.000Z","next_review_at":"2026-08-10T20:23:55.000Z","field_reviews":[]},"quality":{"publication_state":"review","completeness_pct":100,"confidence":"high","unsourced_fields":[]},"extensions":{"legacy_origin":"chain_analysis_and_chain_facts","observation_window":{"started_at":"2026-08-03T20:23:49.000Z","completed_at":"2026-08-03T20:23:55.000Z"},"explicit_unknowns":[["How much rollup activity becomes durable Ethereum blob and settlement fees?","Two quarters of rollup data, L1 costs and blob-fee attribution."],["Who controls effective stake and block building after entity clustering?","A current entity-adjusted stake and builder map."],["How much application demand is unique to L1 rather than routed through rollups?","A wallet and fee cohort separated by execution layer."],["Does ETH burn sustainably exceed issuance across market regimes?","A twelve-month issuance, burn and validator-reward reconciliation."]],"methodology_notes":["Every material field has atomic pending claims; a person must review those claims before publication.","TVL, stablecoin supply, DEX volume, fees, revenue and token prices answer different questions and must not be treated as interchangeable.","Documented decisions, observed outcomes, analyst inferences and unresolved unknowns are kept separate."]}}}'
