WITH canonical_seed(payload) AS (VALUES ('{"chain":"Solana","sources":[{"id":"source:solana:core","title":"Solana core concepts","url":"https://solana.com/docs/core","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current accounts, transactions, programs, consensus and runtime concepts."},{"id":"source:solana:fees-docs","title":"Solana transaction fees","url":"https://solana.com/docs/core/fees","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current base-fee, priority-fee, burn and validator distribution rules."},{"id":"source:solana:validators","title":"Solana validators","url":"https://solana.com/validators","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current validator, stake, voting and reward roles."},{"id":"source:solana:staking","title":"Solana staking and inflation","url":"https://solana.com/staking","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current inflation schedule, staking, epoch rewards and stake-weighted consensus."},{"id":"source:solana:upgrades","title":"Solana upgrades","url":"https://solana.com/upgrades","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated 100M-compute-unit mainnet upgrade and clearly labeled future Alpenglow and slot-time work."},{"id":"source:solana:health","title":"Solana network health report","url":"https://solana.com/news/network-health-report-june-2025","publisher":"Solana Foundation","published_at":"2025-06-20","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Foundation-reported uptime, client diversity, validator count and Nakamoto coefficient; operator-authored, not independent."},{"id":"source:solana:validator-map","title":"Solana validator decentralization report","url":"https://validators.solutions/en/validators/decentralization/","publisher":"Validators Solutions","published_at":"2026-07-20","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated stake distribution, active stake, superminority and Nakamoto coefficient methodology."},{"id":"source:solana:galaxy","title":"Solana Q1 2026 update","url":"https://www.galaxy.com/insights/research/solana-q1-2026-dex-rwa-stablecoins-market-share","publisher":"Galaxy Research","published_at":"2026-05-19","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Independent current analysis of demand, validator economics, client diversity and issuance debate."},{"id":"source:solana:tvl","title":"Solana historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Solana","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:solana:volume","title":"Solana DEX volume API","url":"https://api.llama.fi/overview/dexs/Solana?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:solana:fees","title":"Solana fees API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:solana:revenue","title":"Solana revenue API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:solana:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Solana row and peggedUSD field."},{"id":"source:solana:market","title":"Solana token market data","url":"https://api.coingecko.com/api/v3/coins/solana","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T20:23:49.000Z","observation_completed_at":"2026-08-03T20:23:55.000Z","provider":"Solana Foundation, Validators Solutions, Galaxy Research, DefiLlama and CoinGecko","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":4771768128,"peak_tvl_usd":13205250035,"peak_tvl_date":"2025-09-14","tvl_drawdown_pct":63.86,"stablecoin_supply":{"pegged_usd":15703667264.014225},"dex_volume_30d_usd":49535332624.49999,"dex_volume_change_1m_pct":-24.85,"fees_30d_usd":217022629.81999996,"revenue_30d_usd":94301413.01000011,"scope_boundary":"Vote transactions, user transactions, bot activity, DEX volume and retained users are not interchangeable."},"outcome":{"label":"thriving","summary":"Solana combines deep stablecoins, very high DEX activity and material fees with a large native asset and active upgrades. Drawdowns and validator concentration remain, but repeat product demand supports a thriving outcome.","confidence":"high","as_of":"2026-08-03","source_refs":["source:solana:tvl","source:solana:stables","source:solana:volume","source:solana:fees","source:solana:revenue","source:solana:market","source:solana:validator-map"]},"why":{"summary":"Fast unified execution and low fees attracted trading, payments and consumer products; the same design raises hardware, stake and client-concentration tradeoffs.","confidence":"medium","source_refs":["source:solana:core","source:solana:fees-docs","source:solana:volume","source:solana:stables","source:solana:validator-map"]},"strategic_choices":[{"decision":"Keep parallel execution and composability on one L1.","consequence":"Applications share liquidity and state without rollup bridges, while validators carry heavier infrastructure requirements.","confidence":"high","source_refs":["source:solana:core","source:solana:galaxy"]},{"decision":"Use low base fees, priority fees and inflation-funded staking.","consequence":"Demand is cheap to serve, while security depends on issuance and validator economics.","confidence":"high","source_refs":["source:solana:fees-docs","source:solana:staking"]},{"decision":"Increase capacity and pursue new consensus and client implementations.","consequence":"Performance and resilience may improve, but future features must ship safely before they count.","confidence":"high","source_refs":["source:solana:upgrades","source:solana:health"]}],"counterfactual":{"summary":"A modular design, lower hardware target or lower issuance would trade shared liquidity and throughput for broader operation or less dilution.","confidence":"medium","source_refs":["source:solana:core","source:solana:staking","source:solana:galaxy"]},"watch":[{"signal":"Non-vote fee payers, retained wallets, stablecoins, volume quality, fees and revenue.","implication":"Broad repeat demand would distinguish durable use from bots and reflexive trading.","source_refs":["source:solana:fees","source:solana:volume","source:solana:stables","source:solana:galaxy"]},{"signal":"Stake, validator entities, client share, skip rates and upgrade activation.","implication":"Broader operation and safe upgrades would strengthen resilience.","source_refs":["source:solana:validator-map","source:solana:health","source:solana:upgrades"]}],"unknowns":[{"question":"How much measured activity comes from retained human or institutional users?","resolution_trigger":"A wallet cohort excluding votes, bots and one-time incentive activity."},{"question":"Who controls one-third of stake after grouping related validator entities?","resolution_trigger":"A current entity-adjusted validator and delegation map."},{"question":"How independent are production validator clients by code lineage and stake share?","resolution_trigger":"A reproducible stake-by-client lineage audit."},{"question":"Will Alpenglow and shorter slots improve finality without new concentration or outages?","resolution_trigger":"A post-activation multi-quarter reliability report."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Solana

