INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Solana',
  'Solana chose speed, low fees and a unified execution environment. That gave trading venues, payment products and consumer apps fast composability without bridging between rollups. The cost is demanding validator infrastructure, stake concentration and historically greater sensitivity to client or scheduler failures. Strong product distribution and liquidity outweighed those tradeoffs, making Solana a thriving chain even after a large token and TVL drawdown.',
  'mixed',
  'Solana is thriving. It has deep stablecoins, the highest thirty-day DEX volume in this five-chain wave, substantial fees, a $42.87 billion token and continuing capacity upgrades. TVL and SOL remain far below peaks, and validator economics are concentrated enough to watch, but the chain has repeat product demand rather than only subsidized launch activity.',
  '2026-08-03',
  '[{"id":"source:solana:core","title":"Solana core concepts","url":"https://solana.com/docs/core","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current accounts, transactions, programs, consensus and runtime concepts."},{"id":"source:solana:fees-docs","title":"Solana transaction fees","url":"https://solana.com/docs/core/fees","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current base-fee, priority-fee, burn and validator distribution rules."},{"id":"source:solana:validators","title":"Solana validators","url":"https://solana.com/validators","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current validator, stake, voting and reward roles."},{"id":"source:solana:staking","title":"Solana staking and inflation","url":"https://solana.com/staking","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current inflation schedule, staking, epoch rewards and stake-weighted consensus."},{"id":"source:solana:upgrades","title":"Solana upgrades","url":"https://solana.com/upgrades","publisher":"Solana Foundation","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated 100M-compute-unit mainnet upgrade and clearly labeled future Alpenglow and slot-time work."},{"id":"source:solana:health","title":"Solana network health report","url":"https://solana.com/news/network-health-report-june-2025","publisher":"Solana Foundation","published_at":"2025-06-20","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Foundation-reported uptime, client diversity, validator count and Nakamoto coefficient; operator-authored, not independent."},{"id":"source:solana:validator-map","title":"Solana validator decentralization report","url":"https://validators.solutions/en/validators/decentralization/","publisher":"Validators Solutions","published_at":"2026-07-20","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated stake distribution, active stake, superminority and Nakamoto coefficient methodology."},{"id":"source:solana:galaxy","title":"Solana Q1 2026 update","url":"https://www.galaxy.com/insights/research/solana-q1-2026-dex-rwa-stablecoins-market-share","publisher":"Galaxy Research","published_at":"2026-05-19","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Independent current analysis of demand, validator economics, client diversity and issuance debate."},{"id":"source:solana:tvl","title":"Solana historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Solana","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:solana:volume","title":"Solana DEX volume API","url":"https://api.llama.fi/overview/dexs/Solana?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:solana:fees","title":"Solana fees API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:solana:revenue","title":"Solana revenue API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:solana:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Solana row and peggedUSD field."},{"id":"source:solana:market","title":"Solana token market data","url":"https://api.coingecko.com/api/v3/coins/solana","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:solana","type":"blockchain","slug":"solana","name":"Solana","aliases":[]},"classification":{"subtype":"high-throughput proof-of-stake L1","tags":["svm","proof_of_stake","parallel_execution","sol"],"chains":["Solana"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:solana:status"]},"outcome":{"label":"thriving","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:solana:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Solana is a high-throughput proof-of-stake Layer 1 that executes programs in a shared, parallel runtime. SOL pays fees and secures stake-weighted consensus. Its low-cost design supports trading, payments and consumer applications on one state machine. Reported transaction counts must separate validator votes from user transactions, and DeFi metrics do not describe every payment or application.","as_of":"2026-08-03","claim_ids":["claim:solana:section:what_it_is:1","claim:solana:section:what_it_is:2"]},"what_happened":{"body":"Solana TVL was $4.77 billion at review, 63.86% below its September 2025 series peak of $13.21 billion. Dollar stablecoins were $15.70 billion and thirty-day DEX volume was $49.54 billion, down 24.85% from the prior provider comparison. Fees were $217.02 million and provider-attributed revenue was $94.30 million. SOL was $73.77, 74.85% below its high, with a $42.87 billion market capitalization.","as_of":"2026-08-03","claim_ids":["claim:solana:section:what_happened:1","claim:solana:section:what_happened:2"]},"why_this_outcome":{"body":"Solana chose speed, low fees and a unified execution environment. That gave trading venues, payment products and consumer apps fast composability without bridging between rollups. The cost is demanding validator infrastructure, stake concentration and historically greater sensitivity to client or scheduler failures. Strong product distribution and liquidity outweighed those tradeoffs, making Solana a thriving chain even after a large token and TVL drawdown.","as_of":"2026-08-03","claim_ids":["claim:solana:section:why_this_outcome:1","claim:solana:section:why_this_outcome:2"]},"strategic_choices":{"body":"Solana kept execution on one fast L1, used stake-weighted leaders and votes, and priced signatures plus optional compute priority. It funds validators with inflation and fees while burning part of base fees. The network raised block capacity to 100 million compute units in July 2026 and is preparing Alpenglow and shorter slots, but those future changes must not be described as current consensus.","as_of":"2026-08-03","claim_ids":["claim:solana:section:strategic_choices:1","claim:solana:section:strategic_choices:2"]},"operating_model":{"body":"Stake-weighted validators replay transactions, vote on forks and take turns as leaders. Delegators assign SOL to validator vote accounts. Validators earn protocol issuance, base-fee shares and priority fees. The current system still depends on high-performance hardware and low-latency networking. Independent client work is improving software diversity, but client labels derived from one codebase should not be counted as wholly independent implementations.","as_of":"2026-08-03","claim_ids":["claim:solana:section:operating_model:1","claim:solana:section:operating_model:2"]},"token_and_value_capture":{"body":"SOL pays transaction fees, backs delegated stake and receives protocol issuance. Half of the documented base fee is burned and half goes to validators; priority fees go to the validator. The inflation schedule began at 8% annually, declines by 15% each year and targets 1.5%, but realized supply and yield also depend on participation and protocol changes. CoinGecko observed a $42.87 billion market cap and $46.58 billion fully diluted value.","as_of":"2026-08-03","claim_ids":["claim:solana:section:token_and_value_capture:1","claim:solana:section:token_and_value_capture:2"]},"counterfactual":{"body":"Solana could split activity across rollups or application chains, reducing one-state contention while fragmenting liquidity. Lower hardware requirements would broaden validator access but reduce peak throughput. Lower issuance would reduce dilution but could weaken smaller-validator economics. Slower upgrades would reduce operational change risk while giving up the performance advantage that drives much of Solana demand.","as_of":"2026-08-03","claim_ids":["claim:solana:section:counterfactual:1","claim:solana:section:counterfactual:2"]},"risks_and_unknowns":{"body":"Solana remains exposed to stake and infrastructure concentration, client-correlated bugs, leader and block-builder influence, state growth and upgrade execution risk. Low fees can also support spam or bot activity, so volume and transaction counts do not prove retained human demand. Alpenglow, validator-admission changes and shorter slots remain moving targets. We lack a current entity-adjusted map of stake, clients, fee payers and repeat users.","as_of":"2026-08-03","claim_ids":["claim:solana:section:risks_and_unknowns:1","claim:solana:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Solana is thriving. It has deep stablecoins, the highest thirty-day DEX volume in this five-chain wave, substantial fees, a $42.87 billion token and continuing capacity upgrades. TVL and SOL remain far below peaks, and validator economics are concentrated enough to watch, but the chain has repeat product demand rather than only subsidized launch activity.","as_of":"2026-08-03","claim_ids":["claim:solana:section:lifecycle:1","claim:solana:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued strength in trading, stablecoin settlement and consumer applications. The call improves if retained non-bot users, revenue and stablecoins grow while stake and client concentration fall. It weakens if liquidity is mostly reflexive trading, validator operation consolidates, or major upgrades create instability. Watch non-vote activity, repeat fee payers, DEX quality, stablecoins, revenue, stake distribution, client share, skip rates and Alpenglow activation.","as_of":"2026-08-03","claim_ids":["claim:solana:section:outlook_and_watch:1","claim:solana:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:solana:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":4771768128,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:solana:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":15703667264.014225,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:stablecoins-latest"],"quality_flags":["not_equivalent_to_tvl"]},{"id":"metric:solana:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":49535332624.49999,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:dex-volume-30d"],"quality_flags":["not_unique_users","bot_share_unknown"]},{"id":"metric:solana:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":217022629.81999996,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:fees-30d"],"quality_flags":["provider_scope"]},{"id":"metric:solana:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":94301413.01000011,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:revenue-30d"],"quality_flags":["not_net_income"]},{"id":"metric:solana:token-price:2026-08-03","dimension":"token_price","label":"SOL price","value":73.77,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"current_price.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:token-price"],"quality_flags":[]},{"id":"metric:solana:token-market-cap:2026-08-03","dimension":"token_market_cap","label":"SOL market capitalization","value":42870193713,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"market_cap.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:token-market-cap"],"quality_flags":[]},{"id":"metric:solana:token-fdv:2026-08-03","dimension":"token_fdv","label":"SOL fully diluted value","value":46581202045,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"fully_diluted_valuation.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:solana:metric:token-fdv"],"quality_flags":[]}],"events":[{"id":"event:solana:peak-tvl","type":"market_event","date":"2025-09-14","description":"Solana reached the maximum TVL point in the reviewed series.","claim_ids":["claim:solana:event:peak-tvl"]},{"id":"event:solana:token-ath","type":"market_event","date":"2025-01-19","description":"SOL reached the all-time-high price recorded by CoinGecko.","claim_ids":["claim:solana:event:token-ath"]},{"id":"event:solana:100m-compute","type":"capacity_upgrade","date":"2026-07-29","description":"Solana raised mainnet block capacity from 60 million to 100 million compute units.","claim_ids":["claim:solana:event:100m-compute"]}],"sources":[{"id":"source:solana:core","title":"Solana core concepts","url":"https://solana.com/docs/core","publisher":"Solana Foundation","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current accounts, transactions, programs, consensus and runtime concepts."},{"id":"source:solana:fees-docs","title":"Solana transaction fees","url":"https://solana.com/docs/core/fees","publisher":"Solana Foundation","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current base-fee, priority-fee, burn and validator distribution rules."},{"id":"source:solana:validators","title":"Solana validators","url":"https://solana.com/validators","publisher":"Solana Foundation","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current validator, stake, voting and reward roles."},{"id":"source:solana:staking","title":"Solana staking and inflation","url":"https://solana.com/staking","publisher":"Solana Foundation","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current inflation schedule, staking, epoch rewards and stake-weighted consensus."},{"id":"source:solana:upgrades","title":"Solana upgrades","url":"https://solana.com/upgrades","publisher":"Solana Foundation","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Dated 100M-compute-unit mainnet upgrade and clearly labeled future Alpenglow and slot-time work."},{"id":"source:solana:health","title":"Solana network health report","url":"https://solana.com/news/network-health-report-june-2025","publisher":"Solana Foundation","published_at":"2025-06-20","accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Foundation-reported uptime, client diversity, validator count and Nakamoto coefficient; operator-authored, not independent."},{"id":"source:solana:validator-map","title":"Solana validator decentralization report","url":"https://validators.solutions/en/validators/decentralization/","publisher":"Validators Solutions","published_at":"2026-07-20","accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Dated stake distribution, active stake, superminority and Nakamoto coefficient methodology."},{"id":"source:solana:galaxy","title":"Solana Q1 2026 update","url":"https://www.galaxy.com/insights/research/solana-q1-2026-dex-rwa-stablecoins-market-share","publisher":"Galaxy Research","published_at":"2026-05-19","accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Independent current analysis of demand, validator economics, client diversity and issuance debate."},{"id":"source:solana:tvl","title":"Solana historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Solana","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:solana:volume","title":"Solana DEX volume API","url":"https://api.llama.fi/overview/dexs/Solana?dataType=dailyVolume","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"total30d and change_1m fields."},{"id":"source:solana:fees","title":"Solana fees API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyFees","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:solana:revenue","title":"Solana revenue API","url":"https://api.llama.fi/overview/fees/Solana?dataType=dailyRevenue","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"total30d field."},{"id":"source:solana:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"independent","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Solana row and peggedUSD field."},{"id":"source:solana:market","title":"Solana token market data","url":"https://api.coingecko.com/api/v3/coins/solana","publisher":"CoinGecko","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"aggregator","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"current price, market cap, FDV and all-time-high fields."}],"claims":[{"id":"claim:solana:status","field_path":"status.operating_state","assertion":"Solana was operating at the review date.","value":"operating","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:core","source:solana:validators","source:solana:upgrades","source:solana:tvl"],"evidence_locator":"Current protocol, validator, upgrade and market sources show a live L1.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:outcome","field_path":"outcome.label","assertion":"Solana is classified thriving as of 2026-08-03.","value":"thriving","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:solana:tvl","source:solana:stables","source:solana:volume","source:solana:fees","source:solana:revenue","source:solana:market","source:solana:validator-map"],"evidence_locator":"Capital, stablecoins, trading, economics, token value and validator distribution were reviewed together.","support_direction":"supports","note":"Analyst lifecycle classification; current metrics do not prove a single cause.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:what_it_is:1","field_path":"analysis.sections.what_it_is.body","assertion":"Solana is a proof-of-stake Layer 1 with a parallel program runtime.","value":"Solana is a proof-of-stake Layer 1 with a parallel program runtime.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:core","source:solana:validators"],"evidence_locator":"Current core and validator documentation.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:what_it_is:2","field_path":"analysis.sections.what_it_is.body","assertion":"Vote traffic, user transactions and DeFi observations are different scopes.","value":"Vote traffic, user transactions and DeFi observations are different scopes.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:validators","source:solana:galaxy","source:solana:fees"],"evidence_locator":"Consensus voting and independent demand analysis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:what_happened:1","field_path":"analysis.sections.what_happened.body","assertion":"Solana TVL fell from $13,205,250,035 at the reviewed peak to $4,771,768,128.","value":"Solana TVL fell from $13,205,250,035 at the reviewed peak to $4,771,768,128.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:tvl"],"evidence_locator":"Historical series maximum and latest point.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:what_happened:2","field_path":"analysis.sections.what_happened.body","assertion":"Stablecoins, DEX volume and fees remained large despite capital and token drawdowns.","value":"Stablecoins, DEX volume and fees remained large despite capital and token drawdowns.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:stables","source:solana:volume","source:solana:fees","source:solana:market"],"evidence_locator":"Point-in-time provider observations.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:why_this_outcome:1","field_path":"analysis.sections.why_this_outcome.body","assertion":"Low-cost unified execution helped Solana attract trading, stablecoins and applications.","value":"Low-cost unified execution helped Solana attract trading, stablecoins and applications.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:solana:core","source:solana:fees-docs","source:solana:volume","source:solana:stables"],"evidence_locator":"Design compared with observed demand.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:why_this_outcome:2","field_path":"analysis.sections.why_this_outcome.body","assertion":"Validator cost, stake concentration and client diversity remain the principal resilience tradeoffs.","value":"Validator cost, stake concentration and client diversity remain the principal resilience tradeoffs.","as_of":"2026-08-03","confidence":"high","kind":"inference","source_ids":["source:solana:health","source:solana:validator-map","source:solana:galaxy"],"evidence_locator":"Dated operator and independent validator analysis.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:strategic_choices:1","field_path":"analysis.sections.strategic_choices.body","assertion":"Solana chose monolithic parallel execution, stake-weighted consensus and low base fees.","value":"Solana chose monolithic parallel execution, stake-weighted consensus and low base fees.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:core","source:solana:fees-docs","source:solana:staking"],"evidence_locator":"Current architecture and economics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:strategic_choices:2","field_path":"analysis.sections.strategic_choices.body","assertion":"The 100M-compute-unit upgrade is live, while Alpenglow and shorter slots remain future work.","value":"The 100M-compute-unit upgrade is live, while Alpenglow and shorter slots remain future work.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:upgrades"],"evidence_locator":"Dated mainnet and under-development labels.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:operating_model:1","field_path":"analysis.sections.operating_model.body","assertion":"Stake-weighted validators lead, replay and vote, while delegators assign SOL to vote accounts.","value":"Stake-weighted validators lead, replay and vote, while delegators assign SOL to vote accounts.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:validators","source:solana:staking"],"evidence_locator":"Current consensus and delegation roles.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:operating_model:2","field_path":"analysis.sections.operating_model.body","assertion":"Validator rewards combine issuance and fees, while hardware and client concentration affect resilience.","value":"Validator rewards combine issuance and fees, while hardware and client concentration affect resilience.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:fees-docs","source:solana:validators","source:solana:galaxy"],"evidence_locator":"Current economics and independent assessment.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:token_and_value_capture:1","field_path":"analysis.sections.token_and_value_capture.body","assertion":"SOL captures demand through fees and stake, while inflation funds security and some fees are burned.","value":"SOL captures demand through fees and stake, while inflation funds security and some fees are burned.","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:fees-docs","source:solana:staking"],"evidence_locator":"Current fee and issuance mechanics.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:token_and_value_capture:2","field_path":"analysis.sections.token_and_value_capture.body","assertion":"SOL market cap was $42,870,193,713 and fully diluted value was $46,581,202,045.","value":"market cap 42870193713; FDV 46581202045","as_of":"2026-08-03","confidence":"high","kind":"fact","source_ids":["source:solana:market"],"evidence_locator":"CoinGecko market_data fields.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:counterfactual:1","field_path":"analysis.sections.counterfactual.body","assertion":"A modular design or lower hardware target would trade composability and throughput for broader operation.","value":"A modular design or lower hardware target would trade composability and throughput for broader operation.","as_of":"2026-08-03","confidence":"medium","kind":"counterfactual","source_ids":["source:solana:core","source:solana:galaxy"],"evidence_locator":"Current design compared with alternatives.","support_direction":"supports","note":null,"review":{"state":"pending","reviewer":null,"reviewed_at":null}},{"id":"claim:solana:section:counterfactual:2","field_path":"analysis.sections.counterfactual.body","assertion":"Lower issuance would reduce dilution while changing validator security economics.","value":"Lower issuance would reduce dilution while changing validator security economics.","as_of":"2026-0