WITH canonical_seed(payload) AS (VALUES ('{"chain":"BSC","sources":[{"id":"source:bsc:introduction","title":"BNB Smart Chain introduction","url":"https://docs.bnbchain.org/bnb-smart-chain/introduction/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current PoSA, 45-validator pool, 21-member epoch set, fast finality and fee-only reward design."},{"id":"source:bsc:validators","title":"BSC validator overview","url":"https://docs.bnbchain.org/bnb-smart-chain/validator/overview/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current 45-validator pool and 21-validator epoch selection mechanics."},{"id":"source:bsc:governance","title":"BSC governance overview","url":"https://docs.bnbchain.org/bnb-smart-chain/governance/overview/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current proposal, delegated voting, quorum, threshold and timelock parameters."},{"id":"source:bsc:fermi","title":"Fermi hard fork","url":"https://www.bnbchain.org/en/blog/fermi-hard-fork-accelerates-bsc-to-0-45-second-block-times","publisher":"BNB Chain","published_at":"2026-01-07","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated 0.45-second block-time and fast-finality upgrade."},{"id":"source:bsc:osaka","title":"Osaka and Mendel hard fork","url":"https://www.bnbchain.org/en/blog/osaka-mendel-hard-fork-strengthening-bnb-chain-after-sub-second-speed-gains","publisher":"BNB Chain","published_at":"2026-04-16","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated April 2026 reliability and finality upgrade after sub-second block changes."},{"id":"source:bsc:roadmap","title":"BNB Chain H2 2026 technology roadmap","url":"https://www.bnbchain.org/en/blog/bnb-chain-h2-2026-tech-roadmap-doubling-d