centered distribution created a powerful funnel; compact validation enabled performance while concentrating control.","confidence":"medium","source_refs":["source:bsc:introduction","source:bsc:fermi","source:bsc:vbnb","source:bsc:volume","source:bsc:mev-study"]},"strategic_choices":[{"decision":"Use a compact proof-of-staked-authority validator model.","consequence":"BSC coordinates fast blocks and finality with fewer independent consensus actors.","confidence":"high","source_refs":["source:bsc:introduction","source:bsc:validators"]},{"decision":"Remain EVM-compatible and fee-funded.","consequence":"Developers migrate easily and validators avoid inflationary block rewards.","confidence":"high","source_refs":["source:bsc:introduction"]},{"decision":"Push sub-second blocks and faster finality.","consequence":"User latency improves while infrastructure and builder advantages become more important.","confidence":"high","source_refs":["source:bsc:fermi","source:bsc:osaka","source:bsc:mev-study"]}],"counterfactual":{"summary":"A larger validator and builder set, inflationary rewards or a new runtime would improve some decentralization or design freedom while weakening speed, scarcity or distribution.","confidence":"medium","source_refs":["source:bsc:validators","source:bsc:introduction","source:bsc:mev-study"]},"watch":[{"signal":"Repeat fee payers, stablecoins, volume quality, TVL, fees and revenue.","implication":"Broad repeat activity would confirm demand beyond temporary trading cycles.","source_refs":["source:bsc:stables","source:bsc:volume","source:bsc:tvl","source:bsc:fees"]},{"signal":"Validator entities, delegated stake, builder share, governance turnout and finality incidents.","implication":"Broader control without degraded performance would strengthen the security case.","source_refs":["source:bsc:validators","source:bsc:governance","source:bsc:mev-study"]}],"unknowns":[{"question":"Who controls the validator pool after grouping related entities and delegations?","resolution_trigger":"A current beneficial-owner and delegation map."},{"question":"How concentrated is block building and MEV after the 2026 latency upgrades?","resolution_trigger":"A multi-month receipt-level builder and proposer study."},{"question":"How much BSC demand is organic versus routed by Binance-linked products?","resolution_trigger":"A wallet-acquisition and retention cohort by entry channel."},{"question":"How much BNB value capture comes from BSC rather than exchange and ecosystem utility?","resolution_trigger":"A reconciled burn, fee, staking and cross-product utility model."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end BSC

