-- canonical-profile-start BSC
INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'BSC',
  'BSC paired Ethereum compatibility with much cheaper, faster execution and immediate access to a large BNB-centered user funnel. Developers could reuse EVM tools while traders received sub-second blocks and deep stablecoin liquidity. The compact validator set made those performance choices easier to coordinate, but it concentrates consensus and upgrade influence. BSC thrives because distribution, compatibility and cost beat the decentralization tradeoff for many users.',
  'mixed',
  'BNB Smart Chain is thriving. It combines $13.88 billion of dollar stablecoins, $32.07 billion of monthly DEX volume, positive fees, a large BNB asset and continuing upgrades. TVL remains 77.56% below its peak and its validator and builder model is concentrated. This is a successful low-cost distribution chain whose main weakness is not lack of use, but how much control and token value sit outside a broad independent operator set.',
  '2026-08-03',
  '[{"id":"source:bsc:introduction","title":"BNB Smart Chain introduction","url":"https://docs.bnbchain.org/bnb-smart-chain/introduction/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current PoSA, 45-validator pool, 21-member epoch set, fast finality and fee-only reward design."},{"id":"source:bsc:validators","title":"BSC validator overview","url":"https://docs.bnbchain.org/bnb-smart-chain/validator/overview/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current 45-validator pool and 21-validator epoch selection mechanics."},{"id":"source:bsc:governance","title":"BSC governance overview","url":"https://docs.bnbchain.org/bnb-smart-chain/governance/overview/","publisher":"BNB Chain","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current proposal, delegated voting, quorum, threshold and timelock parameters."},{"id":"source:bsc:fermi","title":"Fermi hard fork","url":"https://www.bnbchain.org/en/blog/fermi-hard-fork-accelerates-bsc-to-0-45-second-block-times","publisher":"BNB Chain","published_at":"2026-01-07","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated 0.45-second block-time and fast-finality upgrade."},{"id":"source:bsc:osaka","title":"Osaka and Mendel hard fork","url":"https://www.bnbchain.org/en/blog/osaka-mendel-hard-fork-strengthening-bnb-chain-after-sub-second-speed-gains","publisher":"BNB Chain","published_at":"2026-04-16","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated April 2026 reliability and finality upgrade after sub-second block changes."},{"id":"source:bsc:roadmap","title":"BNB Chain H2 2026 technology roadmap","url":"https://www.bnbchain.org/en/blog/bnb-chain-h2-2026-tech-roadmap-doubling-down-on-speed","publisher":"BNB Chain","published_at":"2026-07-08","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Operator-reported H1 performance changes and clearly future H2 objectives."},{"id":"source:bsc:mev-study","title":"MEV in Binance Builder","url":"https://arxiv.org/abs/2602.15395","publisher":"Independent academic preprint","published_at":"2026-02-17","source_role":"independent","tier":"A","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Empirical analysis of builder concentration and latency advantages on BSC; preprint, not peer-reviewed final publication."},{"id":"source:bsc:vbnb","title":"VanEck BNB ETF prospectus","url":"https://www.vaneck.com/us/en/investments/bnb-etf-vbnb/vbnb-prospectus.pdf","publisher":"VanEck filing","published_at":"2026-04-30","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Third-party regulated-product disclosure on BNB origin, utility, burns and validator concentration risk; issuer filing, not protocol assurance."},{"id":"source:bsc:tvl","title":"BSC historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/BSC","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:bsc:volume","title":"BSC DEX volume API","url":"https://api.llama.fi/overview/dexs/BSC?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:bsc:fees","title":"BSC fees API","url":"https://api.llama.fi/overview/fees/BSC?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:bsc:revenue","title":"BSC revenue API","url":"https://api.llama.fi/overview/fees/BSC?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:bsc:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"BSC row and peggedUSD field."},{"id":"source:bsc:market","title":"BSC token market data","url":"https://api.coingecko.com/api/v3/coins/binancecoin","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:bsc","type":"blockchain","slug":"bsc","name":"BNB Smart Chain","aliases":["BSC"]},"classification":{"subtype":"EVM proof-of-staked-authority L1","tags":["evm","posa","bnb","fast_finality"],"chains":["BNB Smart Chain"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:bsc:status"]},"outcome":{"label":"thriving","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:bsc:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"BNB Smart Chain is an EVM-compatible Layer 1 optimized for low fees and fast finality. BNB pays gas, secures delegated staking and participates in governance. A pool of 45 validators supplies a 21-validator consensus set each epoch. BSC is technically distinct from the Binance exchange, although the BNB brand and wider Binance-linked ecosystem provide distribution that a chain-only metric cannot isolate.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:what_it_is:1","claim:bsc:section:what_it_is:2"]},"what_happened":{"body":"BSC TVL was $4.89 billion at review, 77.56% below its May 2021 peak of $21.78 billion. Dollar stablecoins were $13.88 billion and thirty-day DEX volume was $32.07 billion, up 174.83% from the prior provider comparison. Fees were $36.05 million and provider-attributed revenue was $17.90 million. BNB was $590.59 with a $78.64 billion market cap, 56.89% below its high.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:what_happened:1","claim:bsc:section:what_happened:2"]},"why_this_outcome":{"body":"BSC paired Ethereum compatibility with much cheaper, faster execution and immediate access to a large BNB-centered user funnel. Developers could reuse EVM tools while traders received sub-second blocks and deep stablecoin liquidity. The compact validator set made those performance choices easier to coordinate, but it concentrates consensus and upgrade influence. BSC thrives because distribution, compatibility and cost beat the decentralization tradeoff for many users.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:why_this_outcome:1","claim:bsc:section:why_this_outcome:2"]},"strategic_choices":{"body":"BSC chose Proof of Staked Authority rather than a large open validator set, full EVM compatibility rather than a new developer runtime, and fee-funded validators rather than inflationary block rewards. The Fermi upgrade cut block time to 0.45 seconds; Osaka and Mendel then emphasized stability and finality. The H2 2026 roadmap targets more speed, but future throughput goals are not current production facts.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:strategic_choices:1","claim:bsc:section:strategic_choices:2"]},"operating_model":{"body":"BNB holders delegate to validator candidates. The 45-validator pool is divided into 21 Cabinet and 24 Candidate validators, and an epoch group of 21 produces blocks. Fast-finality votes finalize within roughly two blocks when two-thirds vote normally; the chain falls back to probabilistic finality otherwise. Current governance uses delegated staking credit, proposal thresholds, quorum and a timelock.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:operating_model:1","claim:bsc:section:operating_model:2"]},"token_and_value_capture":{"body":"BNB pays gas, secures staking and governance, and receives utility across the wider BNB and Binance-linked ecosystem. Validators earn transaction fees rather than inflationary block rewards, and burn mechanisms reduce supply. That means BNB value cannot be attributed to BSC fees alone. CoinGecko observed a $78.64 billion market capitalization and fully diluted value.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:token_and_value_capture:1","claim:bsc:section:token_and_value_capture:2"]},"counterfactual":{"body":"BSC could enlarge the active validator set and open block building further, improving censorship resistance while making sub-second coordination harder. It could use inflationary rewards to support more validators, reducing fee dependence at the cost of dilution. It could also differentiate from Ethereum tooling, gaining protocol freedom while losing easy developer migration. Its success is tied to deliberately choosing the opposite tradeoffs.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:counterfactual:1","claim:bsc:section:counterfactual:2"]},"risks_and_unknowns":{"body":"BSC faces validator, stake, governance, builder and infrastructure concentration; a small coordinated set can respond quickly but creates censorship and control risk. Sub-second blocks increase latency advantages, and independent research reports concentrated builder flow. The chain also inherits smart-contract, token-quality and bridge risks common to a low-cost EVM ecosystem. We lack an entity-adjusted validator, delegator and builder-control map.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:risks_and_unknowns:1","claim:bsc:section:risks_and_unknowns:2"]},"lifecycle":{"body":"BNB Smart Chain is thriving. It combines $13.88 billion of dollar stablecoins, $32.07 billion of monthly DEX volume, positive fees, a large BNB asset and continuing upgrades. TVL remains 77.56% below its peak and its validator and builder model is concentrated. This is a successful low-cost distribution chain whose main weakness is not lack of use, but how much control and token value sit outside a broad independent operator set.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:lifecycle:1","claim:bsc:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued strength in low-cost trading and stablecoin activity. The call improves if validator ownership, delegations and block building diversify without degrading finality. It weakens if volume is temporary, Binance-linked distribution erodes, or latency concentration turns into persistent extraction or censorship. Watch repeat fee payers, stablecoins, TVL, volume quality, validator entities, stake, builder share, governance participation and burn-versus-fee economics.","as_of":"2026-08-03","claim_ids":["claim:bsc:section:outlook_and_watch:1","claim:bsc:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:bsc:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":4887527777,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:tvl-latest"],"quality_flags":[]},{"id":"metric:bsc:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":13875571145.029724,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:stablecoins-latest"],"quality_flags":["not_equivalent_to_tvl"]},{"id":"metric:bsc:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":32070810558.109997,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:dex-volume-30d"],"quality_flags":["not_unique_users"]},{"id":"metric:bsc:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":36050645.600000046,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:fees-30d"],"quality_flags":["provider_scope"]},{"id":"metric:bsc:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":17901232.839999985,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:revenue-30d"],"quality_flags":["not_net_income"]},{"id":"metric:bsc:token-price:2026-08-03","dimension":"token_price","label":"BNB price","value":590.59,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"current_price.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:token-price"],"quality_flags":["cross_product_token"]},{"id":"metric:bsc:token-market-cap:2026-08-03","dimension":"token_market_cap","label":"BNB market capitalization","value":78641573138,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"market_cap.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:token-market-cap"],"quality_flags":["cross_product_token"]},{"id":"metric:bsc:token-fdv:2026-08-03","dimension":"token_fdv","label":"BNB fully diluted value","value":78641572193,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"fully_diluted_valuation.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:bsc:metric:token-fdv"],"quality_flags":["cross_product_token"]}],"events":[{"id":"event:bsc:peak-tvl","type":"market_event","date":"2021-05-05","description":"BSC reached the maximum TVL point in the reviewed series.","claim_ids":["claim:bsc:event:peak-tvl"]},{"id":"event:bsc:fermi","type":"performance_upgrade","date":"2026-01-14","description":"Fermi reduced BSC mainnet block time to 0.45 seconds and changed finality rules.","claim_ids":["claim:bsc:event:fermi"]},{"id":"event:bsc:osaka-mendel","type":"reliability_upgrade","date":"2026-04-28","description":"Osaka and Mendel added reliability and finality changes after the sub-second block upgrades.","claim_ids":["claim:bsc:event:osaka-mendel"]}],"sources":[{"id":"source:bsc:introduction","title":"BNB Smart Chain introduction","url":"https://docs.bnbchain.org/bnb-smart-chain/introduction/","publisher":"BNB Chain","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current PoSA, 45-validator pool, 21-member epoch set, fast finality and fee-only reward design."},{"id":"source:bsc:validators","title":"BSC validator overview","url":"https://docs.bnbchain.org/bnb-smart-chain/validator/overview/","publisher":"BNB Chain","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current 45-validator pool and 21-validator epoch selection mechanics."},{"id":"source:bsc:governance","title":"BSC governance overview","url":"https://docs.bnbchain.org/bnb-smart-chain/governance/overview/","publisher":"BNB Chain","published_at":null,"accessed_at":"2026-08-03T20:23:55.000Z","archive_url":null,"tier":"B","role":"primary","access_state":"reachable","checked_at":"2026-08-03T20:23:55.000Z","content_hash":null,"evidence_locator":"Current proposal, delegated voting, quorum, threshold and timelock parameters."},{"id":"source:bsc:fermi","title":"Fermi hard fork","url":"https://www.bnbchain.org/en/blog/fermi-hard-f