_pct":18.09,"stablecoin_supply":{"pegged_usd":4769830197.736418},"dex_volume_30d_usd":21848035085.089993,"dex_volume_change_1m_pct":-12.3,"fees_30d_usd":42573484.40999999,"revenue_30d_usd":14333813.709999997,"security_boundary":"Stage labels are dated maturity opinions; Base remains an L2 with sequencer, proof and upgrade roles distinct from Ethereum L1."},"outcome":{"label":"thriving","summary":"Base has retained capital near peak, built deep stablecoin and trading demand, and produces material fees through a powerful Coinbase funnel. Centralized operation remains, but product outcomes support a thriving call.","confidence":"high","as_of":"2026-08-03","source_refs":["source:base:tvl","source:base:stables","source:base:volume","source:base:fees","source:base:revenue","source:base:l2beat","source:base:coinbase-filing"]},"why":{"summary":"Coinbase distribution, EVM compatibility, ETH gas, low fees and Ethereum settlement reduced user and developer friction while letting Coinbase run a monetized sequencer.","confidence":"medium","source_refs":["source:base:mainnet","source:base:fees-docs","source:base:coinbase-filing","source:base:tvl","source:base:volume","source:base:l2beat"]},"strategic_choices":[{"decision":"Launch as an ETH-gas OP Stack rollup without a token.","consequence":"Base reduced onboarding friction and speculation while using Ethereum settlement.","confidence":"high","source_refs":["source:base:mainnet","source:base:fees-docs"]},{"decision":"Use Coinbase distribution and a Coinbase sequencer.","consequence":"Growth and monetization improved while operation stayed concentrated.","confidence":"high","source_refs":["source:base:mainnet","source:base:coinbase-filing","source:base:l2beat"]},{"decision":"Add fault proofs, a council and independent upgrade control.","consequence":"User exits and governance resilience improved, while trusted roles and instant upgrades remain.","confidence":"high","source_refs":["source:base:security-council","source:base:l2beat"]}],"counterfactual":{"summary":"A launch token, decentralized sequencer or continued shared Superchain governance would alter incentives, regulatory exposure, performance and product control.","confidence":"medium","source_refs":["source:base:mainnet","source:base:token-exploration","source:base:l2beat"]},"watch":[{"signal":"Retained wallets, stablecoins, DEX quality, fees, L1 costs and sequencer margins.","implication":"Durable user and economic growth would confirm the distribution advantage.","source_refs":["source:base:stables","source:base:volume","source:base:fees","source:base:revenue","source:base:coinbase-filing"]},{"signal":"Sequencer, proposer, proof, council, upgrade and token changes.","implication":"Broader control and credible proofs would improve the security case.","source_refs":["source:base:l2beat","source:base:security-council","source:base:token-exploration"]}],"unknowns":[{"question":"When and how will Base decentralize transaction sequencing?","resolution_trigger":"A production multi-sequencer design with measured control share."},{"question":"Will Base launch a token, and what rights or value capture would it have?","resolution_trigger":"An executed specification and verifiable distribution."},{"question":"Who beneficially controls all coordinator and council keys?","resolution_trigger":"A current signer, delegation and entity map."},{"question":"How much Coinbase funnel activity becomes retained independent application demand?","resolution_trigger":"A cohort by acquisition channel, application and repeat fee payment."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Base

-- canonical-meta-start Base
