    '$.canonical_claim_review', json('{"state":"pending","claims":30,"last_assembled_at":"2026-08-03T20:23:55.000Z","human_approval_required":true}'),
    '$.last_reviewed', '2026-08-03',
    '$.next_review_at', '2026-08-10'
  ),
  updated_at = '2026-08-03'
WHERE chain = 'Base' AND dimension = '_meta';
