//api.llama.fi/overview/dexs/Hyperliquid%20L1?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:hyperliquid-l1:fees","title":"Hyperliquid L1 fees API","url":"https://api.llama.fi/overview/fees/Hyperliquid%20L1?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:hyperliquid-l1:revenue","title":"Hyperliquid L1 revenue API","url":"https://api.llama.fi/overview/fees/Hyperliquid%20L1?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:hyperliquid-l1:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Hyperliquid L1 row and peggedUSD field."},{"id":"source:hyperliquid-l1:market","title":"Hyperliquid L1 token market data","url":"https://api.coingecko.com/api/v3/coins/hyperliquid","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}],"forensic_analysis":{"version":"forensic-analysis-v1","observation_snapshot":{"observed_at":"2026-08-03T20:23:49.000Z","observation_completed_at":"2026-08-03T20:23:55.000Z","provider":"Hyperliquid documentation, third-party filings, independent validator analysis, DefiLlama and CoinGecko","historical_tvl_point_date":"2026-08-03","latest_tvl_usd":1227166876,"peak_tvl_usd":2770195837,"peak_tvl_date":"2025-09-19","tvl_drawdown_pct":55.7,"stablecoin_supply":{"pegged_usd":6227379685.931841},"dex_volume_30d_usd":5923610513.960001,"dex_volume_change_1m_pct":-54.12,"fees_30d_usd":106569921.08000003,"revenue_30d_usd":37468452.71999998,"product_boundary":"Perpetuals, spot, HyperEVM, HLP, bridge balances, TVL, fees and revenue require separate attribution."},"outcome":{"label":"thriving","summary":"Hyperliquid L1 has a powerful trading product, deep stablecoins, substantial fees and a valuable token. Recent capital and volume drawdowns and concentrated validation remain, but product-market fit supports a thriving outcome.","confidence":"high","as_of":"2026-08-03","source_refs":["source:hyperliquid-l1:tvl","source:hyperliquid-l1:stables","source:hyperliquid-l1:volume","source:hyperliquid-l1:fees","source:hyperliquid-l1:revenue","source:hyperliquid-l1:market","source:hyperliquid-l1:stake-report"]},"why":{"summary":"A trading-first custom L1 integrated execution, liquidity, fee routing and token incentives; vertical integration improved UX while concentrating consensus and market controls.","confidence":"medium","source_refs":["source:hyperliquid-l1:about","source:hyperliquid-l1:fees-docs","source:hyperliquid-l1:fees","source:hyperliquid-l1:market","source:hyperliquid-l1:stake-report"]},"strategic_choices":[{"decision":"Build native order books on a custom L1.","consequence":"Hyperliquid optimized trading performance while assuming custom consensus and bridge risk.","confidence":"high","source_refs":["source:hyperliquid-l1:about","source:hyperliquid-l1:bridge"]},{"decision":"Share HyperBFT between HyperCore and HyperEVM.","consequence":"Liquidity and applications compose directly, while failures can cross product boundaries.","confidence":"high","source_refs":["source:hyperliquid-l1:about","source:hyperliquid-l1:hyperevm"]},{"decision":"Connect HYPE staking, discounts, fee purchases and burns.","consequence":"Users, security and token demand align, while future emissions and stake concentration remain material.","confidence":"high","source_refs":["source:hyperliquid-l1:staking","source:hyperliquid-l1:fees-docs","source:hyperliquid-l1:market"]}],"counterfactual":{"summary":"External settlement, separated execution domains or a wider active validator set would reduce some custom and concentration risks while weakening integrated performance and liquidity.","confidence":"medium","source_refs":["source:hyperliquid-l1:about","source:hyperliquid-l1:bridge","source:hyperliquid-l1:validator-filing"]},"watch":[{"signal":"Perpetual and spot users, volume, fees, HLP results, burns and emissions.","implication":"Diversified durable economics would confirm product strength beyond one trading cycle.","source_refs":["source:hyperliquid-l1:fees","source:hyperliquid-l1:fees-docs","source:hyperliquid-l1:staking"]},{"signal":"Validator entities, stake share, bridge reserves, oracle incidents and HyperEVM activity.","implication":"Broader control and product diversification would strengthen resilience.","source_refs":["source:hyperliquid-l1:validator-filing","source:hyperliquid-l1:stake-report","source:hyperliquid-l1:bridge","source:hyperliquid-l1:hyperevm"]}],"unknowns":[{"question":"Who controls more than one-third and two-thirds of stake after entity grouping?","resolution_trigger":"A current ledger-derived beneficial-owner map."},{"question":"How much provider fee and revenue data comes from perps, spot, HyperEVM and other products?","resolution_trigger":"A reconciled product-level fee statement."},{"question":"Can third parties independently reproduce, audit and operate the full core node stack?","resolution_trigger":"A reproducible build, state replay and multi-client audit."},{"question":"How durable is demand outside perpetual trading?","resolution_trigger":"Two quarters of HyperEVM, spot and non-trading application cohorts."}],"review":{"status":"current","last_reviewed_at":"2026-08-03","next_review_at":"2026-08-10","reviewer":"chaindump-research-desk"}}}'))
UPDATE chain_facts AS facts
SET
  data = json_set(
    facts.data,
    '$.forensic_analysis', json(json_extract((SELECT payload FROM canonical_seed), '$.forensic_analysis')),
    '$.canonical_profile_ref', 'chain_analysis.profile.canonical_profile'
  ),
  sources = (SELECT json_group_array(json(source_json))
      FROM (
        SELECT source_json
        FROM (
          SELECT
            CASE
              WHEN new_source.value IS NULL THEN old_source.value
              ELSE json_patch(old_source.value, new_source.value)
            END AS source_json,
            old_source.key AS position
          FROM json_each(COALESCE(facts.sources, '[]')) AS old_source
          LEFT JOIN json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
            ON json_extract(new_source.value, '$.url') = json_extract(old_source.value, '$.url')
          WHERE json_extract(old_source.value, '$.url') IS NULL
             OR old_source.key = (
               SELECT MIN(candidate.key)
               FROM json_each(COALESCE(facts.sources, '[]')) AS candidate
               WHERE json_extract(candidate.value, '$.url') = json_extract(old_source.value, '$.url')
             )
          UNION ALL
          SELECT new_source.value AS source_json, 10000 + new_source.key AS position
          FROM json_each(COALESCE(json_extract((SELECT payload FROM canonical_seed), '$.sources'), '[]')) AS new_source
          WHERE NOT EXISTS (
            SELECT 1 FROM json_each(COALESCE(facts.sources, '[]')) AS existing
            WHERE json_extract(existing.value, '$.url') = json_extract(new_source.value, '$.url')
          )
        )
        ORDER BY position
      )),
  updated_at = '2026-08-03'
WHERE facts.chain = json_extract((SELECT payload FROM canonical_seed), '$.chain')
  AND facts.dimension = 'synthesis';
-- canonical-synthesis-end Hyperliquid L1

