INSERT INTO chain_analysis (chain, take, sentiment, trend, updated_at, sources, profile)
VALUES (
  'Hyperliquid L1',
  'Hyperliquid built the trading product first and optimized the chain around an onchain order book rather than waiting for general-purpose applications to create demand. Fast execution, self-custody, integrated liquidity, simple interfaces and community-directed fees attracted traders. HYPE then tied security, discounts and fee-funded burns to that product. The same vertical integration concentrates consensus, oracle, bridge and market controls, but product-market fit has so far outweighed those trust concerns.',
  'mixed',
  'Hyperliquid L1 is thriving. It has more than $6.2 billion of dollar stablecoins, substantial provider-attributed fees and revenue, a $12.07 billion circulating token value and a product that creates repeat trading demand. TVL and monthly volume have fallen sharply from recent highs, and consensus remains concentrated. The chain is successful because the exchange is useful; the open question is whether that success can outgrow its founding operator and trading niche.',
  '2026-08-03',
  '[{"id":"source:hyperliquid-l1:about","title":"About Hyperliquid","url":"https://hyperliquid.gitbook.io/hyperliquid-docs","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current HyperBFT L1 and the HyperCore-versus-HyperEVM execution boundary."},{"id":"source:hyperliquid-l1:staking","title":"Hyperliquid staking","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/hypercore/staking","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current delegated proof of stake, validator requirements, rewards, jailing and absence of automatic slashing."},{"id":"source:hyperliquid-l1:fees-docs","title":"Hyperliquid trading fees","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/trading/fees","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current trading-fee tiers, community routing, assistance-fund HYPE purchases and burns."},{"id":"source:hyperliquid-l1:hyperevm","title":"HyperEVM","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/hyperevm","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current EVM execution, HYPE gas, fee burns and shared HyperBFT security."},{"id":"source:hyperliquid-l1:bridge","title":"Hyperliquid bridge","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/hypercore/bridge","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Current validator-signed Arbitrum USDC bridge, quorum and dispute-lock mechanics."},{"id":"source:hyperliquid-l1:risks","title":"Hyperliquid risk disclosures","url":"https://hyperliquid.gitbook.io/hyperliquid-docs/risks","publisher":"Hyperliquid","source_role":"primary","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Operator-disclosed L1, bridge, oracle, liquidity and HLP-specific risks; not independent assurance."},{"id":"source:hyperliquid-l1:validator-filing","title":"Hyperliquid validator operations disclosure","url":"https://www.sec.gov/Archives/edgar/data/2078856/000119312526272886/d50758ds1a.htm","publisher":"Hyperliquid Strategies SEC filing","published_at":"2026-07-02","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Third-party operator disclosure of 24 active validators and top-21 stake selection; issuer filing, not a protocol audit."},{"id":"source:hyperliquid-l1:stake-report","title":"Hyperliquid validator concentration benchmark","url":"https://perp.wiki/benchmarks/hyperliquid-validator-decentralization-benchmark","publisher":"perp.wiki","published_at":"2026-04-28","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Dated secondary reconstruction of Foundation validator stake concentration; methodology is cited but not an official ledger export."},{"id":"source:hyperliquid-l1:cftc-hype","title":"HYPE futures product filing","url":"https://www.cftc.gov/filings/ptc/ptc0518263585.pdf","publisher":"CFTC filing submitted by a derivatives venue","published_at":"2026-05-18","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Third-party product filing describing HYPE genesis distribution and network roles; filing assertions are not regulator validation."},{"id":"source:hyperliquid-l1:tvl","title":"Hyperliquid L1 historical TVL API","url":"https://api.llama.fi/v2/historicalChainTvl/Hyperliquid%20L1","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Latest and maximum points in the returned daily TVL series."},{"id":"source:hyperliquid-l1:volume","title":"Hyperliquid L1 DEX volume API","url":"https://api.llama.fi/overview/dexs/Hyperliquid%20L1?dataType=dailyVolume","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d and change_1m fields."},{"id":"source:hyperliquid-l1:fees","title":"Hyperliquid L1 fees API","url":"https://api.llama.fi/overview/fees/Hyperliquid%20L1?dataType=dailyFees","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:hyperliquid-l1:revenue","title":"Hyperliquid L1 revenue API","url":"https://api.llama.fi/overview/fees/Hyperliquid%20L1?dataType=dailyRevenue","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"total30d field."},{"id":"source:hyperliquid-l1:stables","title":"Stablecoin supply by chain API","url":"https://stablecoins.llama.fi/stablecoinchains","publisher":"DefiLlama","source_role":"independent","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"Hyperliquid L1 row and peggedUSD field."},{"id":"source:hyperliquid-l1:market","title":"Hyperliquid L1 token market data","url":"https://api.coingecko.com/api/v3/coins/hyperliquid","publisher":"CoinGecko","source_role":"aggregator","tier":"B","checked_at":"2026-08-03T20:23:55.000Z","evidence_locator":"current price, market cap, FDV and all-time-high fields."}]',
  '{"canonical_profile":{"schema":"chaindump-entity-profile","version":1,"identity":{"id":"blockchain:hyperliquid-l1","type":"blockchain","slug":"hyperliquid-l1","name":"Hyperliquid L1","aliases":["Hyperliquid"]},"classification":{"subtype":"trading-optimized delegated-proof-of-stake L1","tags":["hyperbft","hypercore","hyperevm","hype"],"chains":["Hyperliquid L1","Arbitrum"],"jurisdictions":[]},"status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:status"]},"outcome":{"label":"thriving","as_of":"2026-08-03","rule_id":"blockchain-lifecycle-v1","confidence":"high","claim_ids":["claim:hyperliquid-l1:outcome"]},"analysis":{"sections":{"what_it_is":{"body":"Hyperliquid L1 is a trading-optimized blockchain using HyperBFT consensus. HyperCore contains native perpetual-futures and spot order books; HyperEVM is a general-purpose EVM that shares the same consensus. HYPE pays gas, backs delegated stake and receives trading discounts. HyperCore trading, HyperEVM applications, the HLP vault and the Arbitrum USDC bridge are connected products with different risk and metric scopes.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:what_it_is:1","claim:hyperliquid-l1:section:what_it_is:2"]},"what_happened":{"body":"Hyperliquid L1 TVL was $1.23 billion at review, 55.70% below its September 2025 series peak of $2.77 billion. Dollar stablecoins were $6.23 billion and provider-reported thirty-day DEX volume was $5.92 billion, down 54.12% from the prior comparison. Fees were $106.57 million and provider-attributed revenue was $37.47 million. HYPE was $54.24 with a $12.07 billion market cap, 29.43% below its high.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:what_happened:1","claim:hyperliquid-l1:section:what_happened:2"]},"why_this_outcome":{"body":"Hyperliquid built the trading product first and optimized the chain around an onchain order book rather than waiting for general-purpose applications to create demand. Fast execution, self-custody, integrated liquidity, simple interfaces and community-directed fees attracted traders. HYPE then tied security, discounts and fee-funded burns to that product. The same vertical integration concentrates consensus, oracle, bridge and market controls, but product-market fit has so far outweighed those trust concerns.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:why_this_outcome:1","claim:hyperliquid-l1:section:why_this_outcome:2"]},"strategic_choices":{"body":"Hyperliquid chose a custom L1 and native order books instead of deploying only smart contracts on another chain. It added HyperEVM without separating consensus, launched HYPE through a user airdrop, routed fees to HLP, deployers and an assistance fund, and used that fund to buy and burn HYPE. Delegated staking is open by stake rank, but Foundation delegation and a small active set still shape who produces blocks.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:strategic_choices:1","claim:hyperliquid-l1:section:strategic_choices:2"]},"operating_model":{"body":"HyperBFT requires more than two-thirds of stake to commit rounds. Validators enter through delegated stake, with 10,000 HYPE self-delegation and a one-year lock for active status. The network can jail unresponsive validators, but current docs say automatic slashing is not implemented. Third-party filings reported 24 active validators, while the top 21 by stake produce blocks. The Arbitrum bridge also relies on stake-weighted validator signatures and a dispute lock.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:operating_model:1","claim:hyperliquid-l1:section:operating_model:2"]},"token_and_value_capture":{"body":"HYPE is the HyperCore staking asset and HyperEVM gas token. It also provides trading-fee discounts. Trading fees flow to HLP, deployers and the assistance fund; the assistance fund automatically converts fees into HYPE and burns it. Staking rewards come from future emissions, so burns and emissions must be measured together. CoinGecko observed a $12.07 billion market cap and $54.25 billion fully diluted value.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:token_and_value_capture:1","claim:hyperliquid-l1:section:token_and_value_capture:2"]},"counterfactual":{"body":"Hyperliquid could have remained an application on Ethereum or an L2, inheriting broader settlement while accepting slower or more expensive order execution. It could separate HyperCore from HyperEVM security, containing failures while fragmenting liquidity. It could also cap Foundation delegation or expand the active set faster, broadening consensus at the cost of tighter performance coordination. Its success comes from choosing integration over modular neutrality.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:counterfactual:1","claim:hyperliquid-l1:section:counterfactual:2"]},"risks_and_unknowns":{"body":"Users face a young custom L1, concentrated stake, validator-signed bridge, validator-fed oracles, integrated liquidation logic, HLP market risk and regulatory exposure from onchain derivatives. A secondary April 2026 reconstruction estimated that five Foundation validators held about 81% of active stake; that is a dated warning, not a permanent fact, and needs direct ledger revalidation. We also lack a complete entity-level map of validators, core code control and emergency market powers.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:risks_and_unknowns:1","claim:hyperliquid-l1:section:risks_and_unknowns:2"]},"lifecycle":{"body":"Hyperliquid L1 is thriving. It has more than $6.2 billion of dollar stablecoins, substantial provider-attributed fees and revenue, a $12.07 billion circulating token value and a product that creates repeat trading demand. TVL and monthly volume have fallen sharply from recent highs, and consensus remains concentrated. The chain is successful because the exchange is useful; the open question is whether that success can outgrow its founding operator and trading niche.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:lifecycle:1","claim:hyperliquid-l1:section:lifecycle:2"]},"outlook_and_watch":{"body":"The base case is continued strength in perpetual trading, spot liquidity and HyperEVM financial applications. The call improves if third-party validators gain stake, core operation becomes independently reproducible and revenue diversifies beyond perps. It weakens if regulatory constraints, oracle or bridge incidents, HLP losses or trader migration damage the core funnel. Watch perps and spot separately, retained traders, fees, assistance-fund burns, emissions, validator stake, bridge reserves, oracle events and HyperEVM demand.","as_of":"2026-08-03","claim_ids":["claim:hyperliquid-l1:section:outlook_and_watch:1","claim:hyperliquid-l1:section:outlook_and_watch:2"]}}},"metrics":[{"id":"metric:hyperliquid-l1:tvl-latest:2026-08-03","dimension":"tvl","label":"TVL","value":1227166876,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"Latest historicalChainTvl point.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:tvl-latest"],"quality_flags":["not_open_interest"]},{"id":"metric:hyperliquid-l1:stablecoins-latest:2026-08-03","dimension":"stablecoin_supply","label":"Dollar stablecoin supply","value":6227379685.931841,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"peggedUSD field.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:stablecoins-latest"],"quality_flags":["not_equivalent_to_tvl"]},{"id":"metric:hyperliquid-l1:dex-volume-30d:2026-08-03","dimension":"dex_spot_volume","label":"DEX volume (30d)","value":5923610513.960001,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:dex-volume-30d"],"quality_flags":["perpetual_volume_excluded_or_separate","not_unique_users"]},{"id":"metric:hyperliquid-l1:fees-30d:2026-08-03","dimension":"fees","label":"Fees (30d)","value":106569921.08000003,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:fees-30d"],"quality_flags":["provider_scope_requires_product_reconciliation"]},{"id":"metric:hyperliquid-l1:revenue-30d:2026-08-03","dimension":"protocol_revenue","label":"Protocol revenue (30d)","value":37468452.71999998,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"provider-reported rolling 30 days"},"as_of":"2026-08-03","method":"total30d.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:revenue-30d"],"quality_flags":["not_net_income"]},{"id":"metric:hyperliquid-l1:token-price:2026-08-03","dimension":"token_price","label":"HYPE price","value":54.24,"unit":"usd","currency":"USD","window":{"start":null,"end":"2026-08-03","definition":"latest point"},"as_of":"2026-08-03","method":"current_price.usd.","scope":{"product":"blockchain network","chains":[]},"formula":null,"raw_input_ids":[],"claim_ids":["claim:hyperliquid-l1:metric:token-price"],"quality_flags":[]},{"id":"metric:hyperliquid-l1:token-market-cap:2026-08-03","dimension":"token_market_cap","label":"HYPE market capitalization","value":12068814205,"unit":"usd","currency":"USD","window":{"start"